import {createHash} from 'node:crypto';
import {cp, mkdir, readFile, writeFile} from 'node:fs/promises';
import path from 'node:path';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const options = parseArgs(process.argv.slice(2));
const outputDir = path.resolve(root, options.outputDir ?? 'release/offline');
const profile = options.profile ?? 'base';
if (!['base', 'gateway'].includes(profile)) throw new Error('--profile must be base or gateway');

const composeFiles = [
  path.join(root, 'deploy', 'compose', 'compose.yaml'),
  ...(profile === 'gateway' ? [path.join(root, 'deploy', 'compose', 'gateway.yaml')] : []),
];
const composeArgs = composeFiles.flatMap(file => ['-f', file]);
const images = uniqueLines(await commandOutput('docker', ['compose', ...composeArgs, 'config', '--images']));
if (images.length === 0) throw new Error('Compose did not declare any images.');

const imageDir = path.join(outputDir, 'images');
await mkdir(imageDir, {recursive: true});
await cp(path.join(root, 'deploy', 'compose'), path.join(outputDir, 'deploy', 'compose'), {recursive: true});
await cp(path.join(root, 'scripts', 'install-offline-bundle.mjs'), path.join(outputDir, 'install-offline-bundle.mjs'));
if (profile === 'gateway') {
  await mkdir(path.join(outputDir, 'tests', 'e2e'), {recursive: true});
  await cp(path.join(root, 'tests', 'e2e', 'mock-openai.mjs'), path.join(outputDir, 'tests', 'e2e', 'mock-openai.mjs'));
}

const manifestImages = [];
for (const [index, image] of images.entries()) {
  await commandOutput('docker', ['image', 'inspect', image]);
  const imageID = (await commandOutput('docker', ['image', 'inspect', '--format', '{{.Id}}', image])).trim();
  const repoDigests = parseJSON(await commandOutput('docker', ['image', 'inspect', '--format', '{{json .RepoDigests}}', image]), []);
  const digest = repoDigests.find(value => typeof value === 'string' && value.includes('@sha256:'))?.split('@').at(-1) ?? imageID;
  const archiveName = `${String(index + 1).padStart(2, '0')}-${safeName(image)}.tar`;
  const archivePath = path.join(imageDir, archiveName);
  await command('docker', ['save', '--output', archivePath, image]);
  const archive = await readFile(archivePath);
  manifestImages.push({
    reference: image,
    digest,
    imageId: imageID,
    archive: `images/${archiveName}`,
    archiveSha256: createHash('sha256').update(archive).digest('hex'),
    archiveBytes: archive.byteLength,
  });
}

const packageVersion = JSON.parse(await readFile(path.join(root, 'package.json'), 'utf8')).version;
const manifest = {
  format: 'aep-offline-bundle-v1',
  protocolVersion: '1.0',
  packageVersion,
  profile,
  generatedAt: new Date().toISOString(),
  composeFiles: [
    'deploy/compose/compose.yaml',
    ...(profile === 'gateway' ? ['deploy/compose/gateway.yaml'] : []),
    'deploy/compose/offline.yaml',
  ],
  images: manifestImages,
};
await writeFile(path.join(outputDir, 'manifest.json'), `${JSON.stringify(manifest, null, 2)}\n`);
await writeFile(path.join(outputDir, 'SHA256SUMS'), `${manifestImages.map(item => `${item.archiveSha256}  ${item.archive}`).join('\n')}\n`);
await writeFile(path.join(outputDir, 'deploy', 'compose', 'offline.yaml'), offlineCompose(manifestImages));
await writeFile(path.join(outputDir, 'OFFLINE-README.md'), offlineReadme(manifest));
console.log(JSON.stringify({status: 'passed', outputDir, profile, images: manifestImages.map(item => ({reference: item.reference, digest: item.digest, archive: item.archive}))}, null, 2));

function offlineCompose(manifestImages) {
  const serviceImage = name => manifestImages.find(item => item.reference === name)?.reference ?? name;
  const lines = [
    '# Generated by scripts/offline-bundle.mjs. Do not add build contexts here.',
    'services:',
    '  control-service:',
    `    image: ${serviceImage('aep-m0-control-service')}`,
    '    build: null',
  ];
  if (manifestImages.some(item => item.reference === 'aep-m0-gateway-authorizer')) {
    lines.push(
      '  gateway-authorizer:',
      `    image: ${serviceImage('aep-m0-gateway-authorizer')}`,
      '    build: null',
      '  gateway-reconciler:',
      `    image: ${serviceImage('aep-m0-gateway-reconciler')}`,
      '    build: null',
    );
  }
  return `${lines.join('\n')}\n`;
}

function offlineReadme(manifest) {
  const files = manifest.composeFiles.map(file => `- \`${file}\``).join('\n');
  const compose = manifest.composeFiles.map(file => `-f ${file}`).join(' ');
  return `# AEP Offline Bundle\n\nThis bundle was generated for the **${manifest.profile}** profile. It contains the exact image archives and SHA-256 values recorded in \`manifest.json\`.\n\n## Transfer and verify\n\nCopy the complete bundle directory to the air-gapped host. Verify \`SHA256SUMS\` with a trusted local checksum tool before installation.\n\n## One-command install\n\nRun the bundled dependency-free installer from the Bundle directory:\n\n\`\`\`sh\nnode install-offline-bundle.mjs --project aep-offline --port 8080\n\`\`\`\n\nThe installer verifies every archive against both \`SHA256SUMS\` and \`manifest.json\`, loads the images, starts Compose with \`--pull never --no-build\`, and waits for the control service readiness endpoint. Use \`--dry-run\` to inspect actions without changing Docker state.\n\nThe generated \`offline.yaml\` disables build contexts and pins the locally loaded AEP service images. Do not use \`--build\` on the air-gapped host.\n\nCompose inputs:\n\n${files}\n\nThe bundle contains no provider API keys, License private keys, signing seeds, database data, MinIO data, or customer configuration. Supply those through the deployment Secret mechanism.\n`;
}

function parseArgs(args) {
  const result = {};
  for (let index = 0; index < args.length; index += 1) {
    const arg = args[index];
    if (!arg.startsWith('--')) throw new Error(`Unexpected argument: ${arg}`);
    const [rawKey, inline] = arg.slice(2).split('=', 2);
    const value = inline ?? args[++index];
    if (!value || value.startsWith('--')) throw new Error(`Missing value for --${rawKey}`);
    const key = rawKey === 'output-dir' ? 'outputDir' : rawKey;
    result[key] = value;
  }
  return result;
}

function uniqueLines(value) {
  return [...new Set(value.split(/\r?\n/).map(line => line.trim()).filter(Boolean))];
}

function safeName(value) {
  return value.replaceAll('@', '_at_').replaceAll('/', '_').replaceAll(':', '_').replaceAll('=', '_').replaceAll('.', '_');
}

function parseJSON(value, fallback) {
  try { return JSON.parse(value); } catch { return fallback; }
}

function commandOutput(executable, args) {
  return new Promise((resolve, reject) => {
    const child = spawn(executable, args, {cwd: root, stdio: ['ignore', 'pipe', 'pipe'], shell: false});
    const stdout = [], stderr = [];
    child.stdout.on('data', chunk => stdout.push(Buffer.from(chunk)));
    child.stderr.on('data', chunk => stderr.push(Buffer.from(chunk)));
    child.on('error', reject);
    child.on('exit', code => code === 0
      ? resolve(Buffer.concat(stdout).toString('utf8'))
      : reject(new Error(`${executable} ${args.join(' ')} exited with ${code}: ${Buffer.concat(stderr).toString('utf8').trim()}`)));
  });
}

function command(executable, args) {
  return new Promise((resolve, reject) => {
    const child = spawn(executable, args, {cwd: root, stdio: 'inherit', shell: false});
    child.on('error', reject);
    child.on('exit', code => code === 0 ? resolve() : reject(new Error(`${executable} ${args.join(' ')} exited with ${code}`)));
  });
}
